using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Mbb.Archive.Modules.AccessControl.Domain.Roles;namespace Mbb.Archive.Modules.AccessControl.Infrastructure.Persistence;
internal sealed class RoleConfig:IEntityTypeConfiguration<Role>{public void Configure(EntityTypeBuilder<Role>b){b.ToTable("roles","access");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(100);b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(300);b.HasIndex(x=>x.Code).IsUnique();b.HasMany(x=>x.Permissions).WithOne().HasForeignKey(x=>x.RoleId).OnDelete(DeleteBehavior.Cascade);b.Metadata.FindNavigation(nameof(Role.Permissions))?.SetPropertyAccessMode(PropertyAccessMode.Field);b.Ignore(x=>x.DomainEvents);}}
internal sealed class PermissionConfig:IEntityTypeConfiguration<RolePermission>{public void Configure(EntityTypeBuilder<RolePermission>b){b.ToTable("role_permissions","access");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.RoleId).HasColumnName("role_id");b.Property(x=>x.Permission).HasColumnName("permission").HasMaxLength(200);b.HasIndex(x=>new{x.RoleId,x.Permission}).IsUnique();}}
internal sealed class UserRoleConfig:IEntityTypeConfiguration<UserRole>{public void Configure(EntityTypeBuilder<UserRole>b){b.ToTable("user_roles","access");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.SubjectId).HasColumnName("subject_id").HasMaxLength(300);b.Property(x=>x.RoleId).HasColumnName("role_id");b.HasIndex(x=>new{x.SubjectId,x.RoleId}).IsUnique();}}
